INSERT INTO questions (section_id, topic, stem, choices, correct_index, explanation, difficulty, cognitive_level)
VALUES

-- Q1: easy / L1 — Simple vs complex capital structure definition
(2, 'Earnings Per Share', 'Under ASC 260, what characteristic distinguishes a complex capital structure from a simple capital structure?', '["The entity has outstanding securities that could potentially dilute EPS", "The entity has more than one class of common stock outstanding", "The entity reports both continuing and discontinued operations", "The entity has both cumulative and noncumulative preferred stock"]'::jsonb, 0, 'Under ASC 260-10-15-2, a complex capital structure exists when an entity has outstanding potentially dilutive securities such as options, warrants, or convertible instruments. A simple capital structure has no such securities. Choice B is incorrect because having multiple stock classes alone does not create a complex structure unless those classes include potentially dilutive conversion features.', 'easy', 1),

-- Q2: easy / L1 — Which entities must present EPS
(2, 'Earnings Per Share', 'Under U.S. GAAP, which type of entity is required to present earnings per share on the face of the income statement?', '["All entities that prepare financial statements under GAAP", "Any entity with more than $10 million in total assets", "Public entities with common stock or potential common stock traded on a public market", "All entities that have both preferred and common stock outstanding"]'::jsonb, 2, 'Under ASC 260-10-15-2, only public entities with common stock or potential common stock traded in a public market must present EPS. Nonpublic entities may voluntarily disclose EPS but are not required to do so. Choice A is incorrect because private entities have no EPS presentation requirement, making EPS disclosure a public-entity obligation only.', 'easy', 1),

-- Q3: easy / L1 — Dual presentation requirement (basic and diluted)
(2, 'Earnings Per Share', 'What EPS figures must a public company with a complex capital structure present on its income statement?', '["Basic EPS only, with diluted EPS disclosed in the notes", "Both basic EPS and diluted EPS, each with equal prominence", "Diluted EPS only, since it is the more conservative measure", "Basic EPS on the income statement and diluted EPS on the balance sheet"]'::jsonb, 1, 'Under ASC 260-10-45-3, public entities with complex capital structures must present both basic and diluted EPS with equal prominence on the face of the income statement for income from continuing operations and for net income. Choice A is incorrect because diluted EPS must appear on the income statement itself, not merely in footnote disclosures.', 'easy', 1),

-- Q4: hard / L3 — Two-class method with participating securities
(2, 'Earnings Per Share', 'Grandview Industries reports net income of $1,200,000 for the year ended December 31, 2025. The company has 300,000 weighted-average common shares and 50,000 shares of participating preferred stock that shares equally in undistributed earnings after receiving a $2 per share annual dividend. All preferred dividends were declared. Under the two-class method, what is basic EPS for common shareholders?', '["$3.67 per share", "$3.33 per share", "$4.00 per share", "$3.14 per share"]'::jsonb, 3, 'Under ASC 260-10-45-59A, participating securities require the two-class method. After deducting the $100,000 preferred dividend (50,000 x $2), undistributed earnings of $1,100,000 are allocated proportionally: common receives 300,000/350,000 x $1,100,000 = $942,857, yielding $3.14 per share. Choice A ($3.67) incorrectly treats all undistributed earnings as belonging solely to common shareholders without allocating to the participating preferred.', 'hard', 3),

-- Q5: medium / L2 — Weighted-average with mid-year treasury stock repurchase
(2, 'Earnings Per Share', 'Falcon Ridge Corp. had 500,000 common shares outstanding on January 1, 2025. On September 1, the company repurchased 60,000 shares as treasury stock. No other share transactions occurred. What is the weighted-average number of shares outstanding for the year?', '["440,000 shares", "480,000 shares", "500,000 shares", "460,000 shares"]'::jsonb, 1, 'Under ASC 260-10-45-10, treasury stock repurchases reduce weighted-average shares from the repurchase date. Falcon Ridge had 500,000 shares for 8 months (January-August) and 440,000 for 4 months (September-December): (500,000 x 8/12) + (440,000 x 4/12) = 480,000. Choice A (440,000) incorrectly uses only the year-end balance without time-weighting the shares outstanding before the repurchase.', 'medium', 2),

-- Q6: medium / L3 — Directional effect of stock buyback on EPS
(2, 'Earnings Per Share', 'Crestwood Holdings announces a $50 million share repurchase program. Assuming net income remains constant and the average market price stays the same, what is the most likely effect of the buyback on the company''s basic EPS?', '["Basic EPS increases because the denominator decreases while the numerator stays the same", "Basic EPS decreases because the repurchase reduces retained earnings", "Basic EPS remains unchanged because treasury stock has no effect on the EPS formula", "Basic EPS increases because the numerator increases from a gain on repurchased shares"]'::jsonb, 0, 'Under ASC 260-10-45-10, share repurchases reduce weighted-average shares outstanding from the repurchase date. With constant net income and fewer shares in the denominator, basic EPS increases. Choice C is incorrect because treasury stock directly reduces the share count used in the EPS computation, unlike balance sheet presentation where it reduces total equity.', 'medium', 3),

-- Q7: medium / L2 — Restricted stock units in diluted EPS
(2, 'Earnings Per Share', 'Silverbrook Corp. has 200,000 weighted-average common shares outstanding and net income of $800,000. The company granted 8,000 restricted stock units (RSUs) at the beginning of 2025 with a three-year vesting period. Average unrecognized compensation cost is $20 per RSU, and the average market price of common stock during 2025 is $40. Using the treasury stock method, what is diluted EPS?', '["$3.85 per share", "$4.00 per share", "$3.88 per share", "$3.92 per share"]'::jsonb, 3, 'Under ASC 260-10-45-29, RSUs are included in diluted EPS using the treasury stock method. Assumed proceeds equal unrecognized compensation cost (8,000 x $20 = $160,000). Shares repurchased at the $40 average market price = 4,000, yielding 4,000 incremental shares. Diluted EPS = $800,000 / 204,000 = $3.92. Choice A ($3.85) incorrectly adds all 8,000 RSU shares without applying the treasury stock method reduction.', 'medium', 2),

-- Q8: medium / L3 — Mid-year actual conversion of convertible bonds
(2, 'Earnings Per Share', 'Ridgeline Corp. has 400,000 weighted-average common shares and net income of $2,000,000 for 2025. On July 1, 2025, $1,000,000 face value of 6% convertible bonds were actually converted into 40,000 common shares. The tax rate is 25%. For diluted EPS, how should the first half of the year''s bond interest be treated?', '["No adjustment is needed because the bonds were actually converted during the year", "The full year''s after-tax interest expense of $45,000 is added to the numerator", "The first half''s after-tax interest of $22,500 is added to the numerator to reflect assumed conversion from January 1", "The full year''s pre-tax interest expense of $60,000 is added to the numerator"]'::jsonb, 2, 'Under ASC 260-10-45-40, when convertible bonds are actually converted mid-period, diluted EPS assumes conversion from January 1. Interest was recorded for January-June: $1,000,000 x 6% x 6/12 = $30,000 pre-tax, or $22,500 after tax ($30,000 x 0.75). Only this amount is added back because interest ceased at conversion. Choice B incorrectly adds a full year of after-tax interest when interest was only incurred for six months.', 'medium', 3),

-- Q9: hard / L4 — Evaluate EPS presentation for discontinued operations
(2, 'Earnings Per Share', 'Meridian Holdings reports income from continuing operations of $5,000,000 and a loss from discontinued operations of $1,200,000. The CFO proposes presenting only diluted EPS for net income on the face of the income statement. The controller argues that separate EPS figures are required for both continuing operations and net income. Which position is correct, and what is the most appropriate presentation?', '["The CFO is correct; only net income EPS is required on the face of the income statement", "The controller is partially correct; EPS is required for continuing operations only, with net income EPS in the notes", "Neither is correct; EPS presentation is optional for all line items when discontinued operations exist", "The controller is correct; EPS for continuing operations and net income must both appear on the income statement, with discontinued operations EPS either on the statement or in the notes"]'::jsonb, 3, 'Under ASC 260-10-45-3, entities must present basic and diluted EPS for income from continuing operations and for net income on the face of the income statement. EPS for discontinued operations may appear either on the statement or in the notes. The CFO''s proposal omits the mandatory continuing operations EPS. Choice A is incorrect because ASC 260 requires EPS for both continuing operations and net income, not just net income.', 'hard', 4),

-- Q10: medium / L2 — Retroactive adjustment for post-period stock split
(2, 'Earnings Per Share', 'Clearwater Industries reported basic EPS of $6.00 for 2025 based on net income of $1,200,000 and 200,000 weighted-average shares. On February 15, 2026, before the 2025 financial statements were issued, the company declared a 2-for-1 stock split. What basic EPS should Clearwater report for 2025?', '["$6.00 per share", "$3.00 per share", "$12.00 per share", "$4.50 per share"]'::jsonb, 1, 'Under ASC 260-10-55-12, stock splits occurring after the balance sheet date but before financial statements are issued must be retroactively reflected in EPS. The 2-for-1 split doubles weighted-average shares to 400,000, reducing basic EPS to $1,200,000 / 400,000 = $3.00. Choice A ($6.00) is incorrect because it ignores the retroactive adjustment required for post-balance-sheet stock splits.', 'medium', 2),

-- Q11: medium / L3 — Bond premium amortization effect on if-converted numerator
(2, 'Earnings Per Share', 'Northgate Corp. issued $2,000,000 face value, 5% convertible bonds at 105 on January 1, 2025. Each $1,000 bond converts into 20 common shares. The premium is amortized over the bond term using the effective interest method. Northgate''s tax rate is 25%. For diluted EPS, what is the effect of the bond premium amortization on the interest adjustment added to the numerator?', '["It increases the interest adjustment because premium amortization is an additional financing cost", "It has no effect because the premium is a balance sheet item that does not affect the EPS numerator", "It decreases the interest adjustment because premium amortization reduces interest expense, lowering the amount added back", "It increases the interest adjustment because the full coupon payment must be added back regardless of amortization"]'::jsonb, 2, 'Under ASC 260-10-45-40, the if-converted method adds back actual after-tax interest expense recorded during the period. Premium amortization reduces interest expense below the coupon amount ($100,000 coupon versus lower effective interest expense). The after-tax add-back uses the reduced interest expense, not the coupon. Choice D is incorrect because premium amortization must be considered — the adjustment reflects income statement interest expense, not cash interest paid.', 'medium', 3),

-- Q12: medium / L2 — After-tax interest savings for if-converted method
(2, 'Earnings Per Share', 'Baxter Manufacturing has $3,000,000 of 8% convertible bonds outstanding for the full year. Each $1,000 bond converts into 25 common shares. The company''s tax rate is 25%. What is the after-tax interest savings added to the diluted EPS numerator under the if-converted method?', '["$180,000", "$240,000", "$60,000", "$200,000"]'::jsonb, 0, 'Under ASC 260-10-45-40, the if-converted method requires adding back interest expense net of tax. Annual interest is $3,000,000 x 8% = $240,000. The after-tax amount is $240,000 x (1 - 0.25) = $180,000. Choice B ($240,000) is incorrect because it uses the full pre-tax interest without adjusting for tax deductibility, which would overstate the numerator adjustment in the diluted EPS computation.', 'medium', 2),

-- Q13: medium / L2 — Year-to-date vs quarterly EPS computation
(2, 'Earnings Per Share', 'Pinehurst Technologies reports quarterly net income of $300,000 in Q1 and $500,000 in Q2, with 100,000 shares outstanding throughout both periods. No preferred dividends exist. Under ASC 260, what year-to-date basic EPS should Pinehurst present at the end of Q2?', '["$5.00 per share", "$3.00 per share", "$4.00 per share", "$8.00 per share"]'::jsonb, 3, 'Under ASC 260-10-45-2, year-to-date EPS is computed using cumulative income divided by weighted-average shares for the year-to-date period, not by averaging quarterly EPS. Cumulative net income is $800,000, and weighted-average shares are 100,000, yielding $8.00 per share. Choice C ($4.00) incorrectly averages the two quarterly EPS amounts ($3.00 + $5.00) / 2, which can distort results when income varies across quarters.', 'medium', 2),

-- Q14: hard / L4 — Multi-security antidilution testing with ranking
(2, 'Earnings Per Share', 'Hawthorne Corp. has basic EPS of $5.00 ($2,000,000 net income, 400,000 shares). Three potentially dilutive securities exist: (1) stock options adding 20,000 incremental shares, (2) 8% convertible bonds adding $60,000 after-tax interest and 20,000 shares, and (3) convertible preferred stock with $50,000 in dividends convertible into 8,000 shares. Determine the proper inclusion order and the resulting diluted EPS.', '["$4.71 per share, including all three securities", "$4.76 per share, excluding both the bonds and preferred stock", "$5.00 per share, excluding all potentially dilutive securities as antidilutive", "$4.68 per share, including options and bonds but excluding the preferred stock"]'::jsonb, 3, 'Under ASC 260-10-45-21, securities are ranked by per-share impact: options ($0.00), bonds ($3.00), preferred ($6.25). Including options reduces EPS to $4.76; adding bonds reduces EPS to $4.68. Testing preferred: $2,110,000 / 448,000 = $4.71, which exceeds $4.68, so preferred is antidilutive and excluded. Diluted EPS is $4.68. Choice A ($4.71) incorrectly includes the antidilutive preferred, which increases rather than decreases EPS.', 'hard', 4),

-- Q15: easy / L2 — EPS for discontinued operations separate computation
(2, 'Earnings Per Share', 'Summerfield Corp. reports income from continuing operations of $750,000 and a loss from discontinued operations of $150,000. The company has 100,000 weighted-average common shares. What is basic EPS for income from continuing operations?', '["$6.00 per share", "$7.50 per share", "$9.00 per share", "$1.50 per share"]'::jsonb, 1, 'Under ASC 260-10-45-3, EPS for income from continuing operations is calculated separately from discontinued operations. Basic EPS for continuing operations = $750,000 / 100,000 = $7.50 per share. Choice A ($6.00) incorrectly deducts the discontinued operations loss from continuing operations income before computing EPS, conflating the two required separate EPS presentations.', 'easy', 2),

-- Q16: medium / L3 — Written put options and reverse treasury stock method
(2, 'Earnings Per Share', 'Brookfield Corp. has written put options obligating it to repurchase 10,000 shares of its common stock at $50 per share. The average market price during 2025 is $40. Net income is $600,000 and weighted-average shares are 150,000. What is the effect of the written put options on diluted EPS?', '["The puts are excluded because they are out of the money", "The puts reduce diluted EPS by adding 10,000 shares to the denominator", "The puts are dilutive and add 2,500 incremental shares to the denominator", "The puts increase diluted EPS because the company would repurchase shares below market price"]'::jsonb, 2, 'Under ASC 260-10-45-35, written put options use the reverse treasury stock method. When the exercise price ($50) exceeds the average market price ($40), the puts are dilutive. The company assumes repurchase of 10,000 shares at $50 ($500,000), then reissues $500,000 / $40 = 12,500 shares at market price, yielding 2,500 net incremental shares. Choice A is incorrect because written puts are dilutive when exercise price exceeds market, the opposite of stock options.', 'medium', 3),

-- Q17: medium / L3 — Contracts settleable in stock or cash
(2, 'Earnings Per Share', 'Westlake Corp. has a forward contract to purchase 5,000 shares of its own stock at $60 per share, settleable in either cash or shares at Westlake''s option. The average market price is $45 per share. For diluted EPS, how should this contract be treated?', '["The contract is excluded from diluted EPS because settlement is at the company''s option", "The contract is included using the treasury stock method as if it were a stock option", "The contract reduces diluted EPS by adding 5,000 shares regardless of settlement method", "The contract is included using the more dilutive of the possible settlement methods"]'::jsonb, 3, 'Under ASC 260-10-45-45, contracts that may be settled in stock or cash are included in diluted EPS using the more dilutive assumption, regardless of the entity''s intended settlement method. Since the exercise price ($60) exceeds market price ($45), this effectively operates as a dilutive written put under the reverse treasury stock method. Choice A is incorrect because the entity''s settlement discretion does not exempt the contract from diluted EPS.', 'medium', 3),

-- Q18: medium / L3 — Reverse stock split retroactive adjustment
(2, 'Earnings Per Share', 'Alpine Manufacturing had 600,000 common shares outstanding throughout 2025 and reported net income of $1,800,000. On January 15, 2026, before the financial statements were issued, Alpine executed a 1-for-3 reverse stock split. What basic EPS should Alpine report for 2025?', '["$3.00 per share", "$9.00 per share", "$1.00 per share", "$6.00 per share"]'::jsonb, 1, 'Under ASC 260-10-55-12, reverse stock splits occurring after the balance sheet date but before financial statement issuance are retroactively reflected in EPS computations. The 1-for-3 reverse split reduces shares from 600,000 to 200,000, yielding basic EPS of $1,800,000 / 200,000 = $9.00. Choice A ($3.00) incorrectly uses the pre-split 600,000 share count, failing to apply the mandatory retroactive adjustment.', 'medium', 3),

-- Q19: easy / L1 — Definition of weighted-average common shares
(2, 'Earnings Per Share', 'Under ASC 260, what does the weighted-average number of common shares outstanding represent?', '["The number of shares outstanding during the period adjusted for the portion of the period they were outstanding", "The total shares authorized by the corporate charter divided by the number of months in the period", "The simple average of the beginning and ending shares outstanding for the period", "The maximum number of shares outstanding at any point during the period"]'::jsonb, 0, 'Under ASC 260-10-45-10, the weighted-average number of common shares is computed by time-weighting shares for the fraction of the period they were outstanding. Shares issued or repurchased mid-period receive proportional weight from the transaction date. Choice C is incorrect because a simple average of beginning and ending balances does not account for the timing of mid-period share transactions.', 'easy', 1),

-- Q20: easy / L1 — Treasury stock method definition
(2, 'Earnings Per Share', 'Under ASC 260, what is the treasury stock method used for in earnings per share calculations?', '["Adjusting the EPS numerator for gains and losses on treasury stock transactions", "Determining the weighted-average shares when treasury stock is held throughout the period", "Computing the incremental dilutive shares assumed from exercise of stock options and warrants", "Calculating the cost of treasury shares repurchased for the statement of cash flows"]'::jsonb, 2, 'Under ASC 260-10-45-22, the treasury stock method determines incremental dilutive shares by assuming options and warrants are exercised at the beginning of the period, with proceeds used to repurchase shares at the average market price. The difference represents the dilutive increment added to the denominator. Choice A is incorrect because the method relates to computing diluted EPS, not accounting for actual treasury stock transactions.', 'easy', 1),

-- Q21: medium / L2 — Assumed conversion from issuance date, not beginning of year
(2, 'Earnings Per Share', 'Lakewood Corp. issued $1,000,000 of 6% convertible bonds on April 1, 2025. Each $1,000 bond converts into 30 common shares. The tax rate is 25%. For the 2025 diluted EPS computation under the if-converted method, from what date is conversion assumed to occur?', '["April 1, 2025, the date the bonds were issued", "January 1, 2025, the beginning of the fiscal year", "December 31, 2025, the end of the fiscal year", "The date the bonds first become convertible under their terms"]'::jsonb, 0, 'Under ASC 260-10-45-40, when potentially dilutive securities are issued during the period, conversion is assumed from the issuance date, not from January 1. For bonds issued April 1, only nine months of after-tax interest ($1,000,000 x 6% x 9/12 x 0.75 = $33,750) is added back and 30,000 shares are weighted for 9/12 of the year. Choice B is incorrect because the beginning-of-year assumption applies only to securities already outstanding at the start of the period.', 'medium', 2),

-- Q22: easy / L1 — Antidilution provision general rule
(2, 'Earnings Per Share', 'Under ASC 260, what is the antidilution provision in earnings per share reporting?', '["Securities with an exercise price below market price are excluded from diluted EPS", "Diluted EPS is rounded up to equal basic EPS whenever the two amounts differ by less than one cent", "Convertible securities issued at a discount are automatically excluded from diluted EPS", "Securities whose inclusion would increase EPS or decrease loss per share are excluded from diluted EPS"]'::jsonb, 3, 'Under ASC 260-10-45-17, antidilutive securities are those whose inclusion would increase EPS from continuing operations or decrease loss per share. Such securities must be excluded to ensure diluted EPS is always equal to or less than basic EPS. Choice A inverts the test for options — options are antidilutive when exercise price exceeds market price, not when it is below market price.', 'easy', 1),

-- Q23: easy / L1 — EPS presented for each class of common stock
(2, 'Earnings Per Share', 'A public company has two classes of common stock outstanding with different dividend rights. Under ASC 260, how should earnings per share be presented?', '["EPS is presented only for the class with the greatest number of shares outstanding", "EPS must be presented separately for each class of common stock", "EPS is presented only for the class of stock that is publicly traded", "EPS is presented as a single combined figure using total shares of both classes"]'::jsonb, 1, 'Under ASC 260-10-45-66, when an entity has multiple classes of common stock with different participation rights, EPS must be presented separately for each class. This ensures investors understand the earnings attributable to their specific class. Choice D is incorrect because combining shares of different classes would obscure the different participation rights and mislead investors about per-share returns.', 'easy', 1),

-- Q24: easy / L1 — Stock dividends and splits retroactive treatment principle
(2, 'Earnings Per Share', 'Under ASC 260, how are stock dividends and stock splits treated in computing weighted-average shares outstanding?', '["They are applied retroactively as if they occurred at the beginning of the earliest period presented", "They are applied prospectively from the declaration date only", "They are time-weighted from the distribution date like new share issuances", "They are applied retroactively only if declared before year-end"]'::jsonb, 0, 'Under ASC 260-10-55-12, stock dividends and stock splits are applied retroactively to all periods presented as if they occurred at the beginning of the earliest period. This ensures comparability across periods. Choice C is incorrect because unlike share issuances for cash, stock dividends and splits do not bring new resources into the entity and therefore must be reflected retroactively rather than time-weighted.', 'easy', 1),

-- Q25: hard / L4 — Evaluate four-security ranking with antidilution exclusion
(2, 'Earnings Per Share', 'Vertex Dynamics reports net income of $3,000,000 with 500,000 weighted-average common shares (basic EPS = $6.00). Four potentially dilutive securities exist: (1) stock options adding 15,000 incremental shares, (2) Series A convertible preferred adding $120,000 dividends and 30,000 shares, (3) 5% convertible bonds adding $75,000 after-tax interest and 25,000 shares, and (4) Series B convertible preferred adding $80,000 dividends and 12,000 shares. Evaluate the proper inclusion order and determine diluted EPS.', '["$5.63 per share, including all four securities", "$5.69 per share, including only options and bonds", "$5.61 per share, including options, bonds, and Series A preferred but excluding Series B preferred", "$5.83 per share, including only the stock options"]'::jsonb, 2, 'Under ASC 260-10-45-21, securities are ranked by per-share impact: options ($0.00), bonds ($3.00), Series A ($4.00), Series B ($6.67). Including options yields $5.83; adding bonds yields $5.69; adding Series A yields $5.61. Series B at $6.67 per-share impact exceeds the running $5.61 EPS, making it antidilutive. Choice A ($5.63) incorrectly includes the antidilutive Series B preferred, which raises rather than lowers computed EPS.', 'hard', 4),

-- Q26: medium / L3 — Participating preferred reducing basic EPS vs non-participating
(2, 'Earnings Per Share', 'Sterling Analytics has 250,000 common shares and 25,000 shares of participating preferred stock with a $4 per share annual dividend that participates equally in undistributed earnings. Net income for 2025 is $1,500,000. All preferred dividends were declared. How does the participation feature affect basic EPS compared to non-participating preferred?', '["It has no effect because preferred dividends are deducted identically regardless of participation rights", "It increases basic EPS because participating preferred receives fewer total distributions", "It decreases basic EPS because undistributed earnings are shared with preferred shareholders under the two-class method", "It decreases basic EPS because participating preferred dividends are doubled under ASC 260"]'::jsonb, 2, 'Under ASC 260-10-45-59A, participating preferred requires the two-class method. Without participation, basic EPS is ($1,500,000 - $100,000) / 250,000 = $5.60. With participation, common receives only 250,000/275,000 of $1,400,000 undistributed earnings = $1,272,727, yielding $5.09. The participation feature allocates undistributed earnings to preferred, reducing common EPS. Choice A is incorrect because participation rights fundamentally change the income allocation methodology.', 'medium', 3),

-- Q27: medium / L2 — Warrants using treasury stock method calculation
(2, 'Earnings Per Share', 'Redstone Corp. has 400,000 weighted-average common shares, net income of $2,000,000, and 20,000 warrants outstanding with an exercise price of $30. The average market price during 2025 is $50. Using the treasury stock method, what is diluted EPS?', '["$4.90 per share", "$4.76 per share", "$5.00 per share", "$4.85 per share"]'::jsonb, 0, 'Under ASC 260-10-45-22, warrants are treated identically to stock options using the treasury stock method. Proceeds from assumed exercise of 20,000 warrants at $30 = $600,000. At the $50 average market price, 12,000 shares are repurchased, yielding 8,000 incremental shares. Diluted EPS = $2,000,000 / 408,000 = $4.90. Choice B ($4.76) incorrectly adds all 20,000 warrant shares without reducing for the assumed treasury stock repurchase.', 'medium', 2),

-- Q28: hard / L4 — Evaluate share-based compensation in assumed proceeds
(2, 'Earnings Per Share', 'Whitfield Industries grants 15,000 stock options on January 1, 2025, with an exercise price of $35 and a fair value of $12 per option. The average market price during 2025 is $50, and average unrecognized compensation cost is $8 per option. Whitfield has 250,000 weighted-average shares and net income of $1,250,000. The controller computed diluted shares using only the exercise price in the treasury stock method. Evaluate the controller''s approach and determine correct diluted EPS.', '["$4.91 per share; the controller''s approach is correct because only exercise price proceeds matter", "$4.96 per share; the controller understated assumed proceeds by excluding unrecognized compensation, resulting in too many incremental shares", "$5.00 per share; the options are antidilutive after including unrecognized compensation in proceeds", "$4.88 per share; the controller should subtract the fair value of options from net income before computing EPS"]'::jsonb, 1, 'Under ASC 260-10-45-29, assumed proceeds for share-based payment awards include exercise price ($525,000) plus average unrecognized compensation ($120,000), totaling $645,000. Repurchased shares = $645,000 / $50 = 12,900, yielding 2,100 incremental shares and diluted EPS of $4.96. The controller''s method using only exercise price yields 4,500 incremental shares and $4.91. Choice A is incorrect because omitting unrecognized compensation overstates dilution.', 'hard', 4),

-- Q29: medium / L2 — Contingently issuable shares when conditions are NOT met
(2, 'Earnings Per Share', 'Brookdale Corp. has 180,000 weighted-average common shares and net income of $900,000. The company agreed to issue 20,000 additional shares to the former owners of an acquired business if cumulative revenues exceed $50 million by December 31, 2025. Actual cumulative revenues through year-end are $42 million. How are the contingent shares treated for basic EPS?', '["The 20,000 shares are included because the contingency period has not yet expired", "A pro-rata portion of 16,800 shares is included based on the $42M/$50M revenue ratio", "The 20,000 shares are excluded because the revenue condition was not met as of the reporting date", "The 20,000 shares are included at a 50% probability weighting of 10,000 shares"]'::jsonb, 2, 'Under ASC 260-10-45-48, contingently issuable shares are included in basic EPS only if all necessary conditions are met as of the reporting date. Since Brookdale''s cumulative revenues of $42 million did not meet the $50 million threshold by December 31, 2025, the 20,000 shares are excluded. Choice A is incorrect because ASC 260 does not include contingent shares based on the possibility of future satisfaction — the condition must actually be met.', 'medium', 2),

-- Q30: hard / L4 — Evaluate if-converted vs two-class for convertible participating preferred
(2, 'Earnings Per Share', 'Veridian Corp. has net income of $4,000,000 with 800,000 weighted-average common shares. It has 100,000 shares of $2 cumulative convertible preferred stock, each convertible into 2 common shares. The preferred stock also participates equally in undistributed earnings above the stated dividend. The CFO must choose between the if-converted method and the two-class method for computing diluted EPS. Which approach should Veridian use?', '["The if-converted method, yielding $4.00 per share, because it produces the more dilutive result", "The two-class method must always be used when preferred stock participates in earnings, yielding $4.22 per share", "Both methods must be presented side by side in the financial statement notes", "The if-converted method applies only to preferred dividends while the two-class method applies to undistributed earnings, yielding a blended $4.11 per share"]'::jsonb, 0, 'Under ASC 260-10-45-60A, when convertible preferred stock also participates in undistributed earnings, the entity computes diluted EPS using both methods and reports the more dilutive result. If-converted yields $4,000,000 / 1,000,000 = $4.00. Two-class allocates 800,000/900,000 of $3,800,000 undistributed to common, yielding $4.22. Since $4.00 is more dilutive, the if-converted method is used. Choice B is incorrect because participation alone does not mandate the two-class method when conversion is more dilutive.', 'hard', 4)

;

COMMIT;
